use strict; use warnings;
open(my $fh, '<', $ARGV[0]) or die; local $/ = "\0"; my @files = <$fh>; close $fh;
my $n = 0;
for my $f (@files) {
    chomp $f;
    next if $f =~ m{^(pnpm-lock\.yaml|Cargo\.lock|docs/archive/)};
    next if $f =~ m{\.(png|jpg|svg|ico|woff2?|node|wasm)$};
    next unless -f $f;
    open(my $in, '<:raw', $f) or next; local $/ = undef; my $s = <$in>; close $in;
    next if $s =~ /\0/;
    my $o = $s;
    $s =~ s{\@oxc-react-docgen/cli(?![A-Za-z0-9])}{\@orin-dx/caliper-docgen}g;
    $s =~ s{\@oxc-react-docgen/}{\@orin-dx/caliper-docgen-}g;
    $s =~ s/OxcReactDocgen/CaliperDocgen/g;
    $s =~ s/oxcReactDocgen/caliperDocgen/g;
    $s =~ s/oxc_react_docgen/caliper_docgen/g;
    $s =~ s/oxc-react-docgen/caliper-docgen/g;
    if ($s ne $o) { open(my $out, '>:raw', $f) or die; print $out $s; close $out; $n++; }
    $/ = "\0";
}
print "rewrote $n files\n";

