import json, re
from collections import Counter, defaultdict

res = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-results'
inp = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'
names = ['mantine', 'chakra', 'antd', 'shadcn', 'spectrum']


def clean(n):
    return re.sub(r' \(.*\)$', '', n)


def classify(src, name):
    """Describe how `name` is declared, from its declaration line(s)."""
    n = re.escape(name.split('.')[-1])
    m = re.search(rf'(?:export\s+)?(?:default\s+)?(?:declare\s+)?(const|let|var)\s+{n}\b\s*(:[^=]+)?=\s*([^\n]{{0,160}})', src)
    if m:
        ann, rhs = m.group(2) or '', m.group(3)
        if ann.strip():
            return 'const with type annotation: ' + re.sub(r'<.*', '<…>', ann.strip(': ').strip())[:30]
        c = re.match(r'\s*(?:React\.)?([A-Za-z_$][\w$.]*)\s*(<[^(]*>)?\s*\(', rhs)
        if c:
            return f"call: {c.group(1)}{'<T>' if c.group(2) else ''}"
        if re.match(r'\s*(async\s*)?\(', rhs) or re.match(r'\s*(async\s*)?[A-Za-z_$][\w$]*\s*=>', rhs):
            return 'arrow function'
        return 'const = other: ' + rhs[:30]
    if re.search(rf'function\s+{n}\b', src):
        return 'function declaration'
    if re.search(rf'class\s+{n}\b', src):
        return 'class'
    if re.search(rf'\b{n}\.(\w+)\s*=', src):
        return 'assigned member'
    return 'not found by name'


tot = Counter()
by_project = {}
for n in names:
    root = f'{inp}/{n}/'
    rdt = json.load(open(f'{res}/{n}.rdt.dump.json'))
    raw = open(f'{res}/{n}.caliper.dump.json').read()
    cal = json.loads(raw[raw.index('{'):])['components']
    got = {(c['filePath'], clean(c['displayName'])) for c in cal.values()}
    kinds = Counter()
    total_missed = 0
    for comp in rdt:
        mine = [p for p, v in comp['props'].items() if ('bench-inputs/' + n + '/') in v['parent'] and '/node_modules/' not in v['parent']]
        if not mine or (comp['file'], comp['name']) in got:
            continue
        total_missed += 1
        try:
            src = open(comp['file']).read()
        except Exception:
            continue
        kinds[classify(src, comp['name'])] += 1
    by_project[n] = (total_missed, kinds)
    tot.update(kinds)

for n in names:
    total, kinds = by_project[n]
    print(f'\n{n}: {total} components RDT found with declared props that Caliper did not')
    for k, v in kinds.most_common(8):
        print(f'  {v:4d}  {k}')
print('\nAll five, by shape:')
for k, v in tot.most_common(14):
    print(f'  {v:4d}  {k}')

