import json, re
from collections import Counter, defaultdict

res = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-results'
inp = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'
names = ['mantine', 'chakra', 'antd', 'shadcn', 'spectrum']


def clean(n):
    return re.sub(r' \(.*\)$', '', n)


def norm(n):
    n = clean(n).split('/')[-1].split('.')[-1]
    return re.sub(r'[^a-z0-9]', '', n.lower())


def plausible(name):
    base = clean(name).split('/')[-1]
    return bool(re.match(r'[A-Z]', base)) and not re.match(r'use[A-Z]', base) and not base.startswith('generate')


def classify(src, name):
    n = re.escape(name.split('/')[-1].split('.')[-1])
    m = re.search(rf'(?:const|let|var)\s+{n}\b\s*(:[^=\n]+)?=\s*([^\n]{{0,200}})', src)
    if m:
        rhs = m.group(2)
        c = re.match(r'\s*(?:React\.)?([A-Za-z_$][\w$.]*)\s*(<)?', rhs)
        if c and c.group(1) not in ('async',) and (c.group(2) or re.match(r'\s*[\w$.]+\s*\(', rhs)) and not rhs.lstrip().startswith('('):
            return f"wrapper call: {c.group(1)}" + ('<T>' if c.group(2) else '(…)')
        if re.match(r'\s*(async\s*)?\(', rhs) or re.match(r'\s*(async\s*)?[A-Za-z_$][\w$]*\s*=>', rhs):
            return 'arrow function'
        return 'other const'
    if re.search(rf'function\s+{n}\b', src):
        return 'function declaration'
    if re.search(rf'class\s+{n}\b', src):
        return 'class'
    return 'no declaration of that name'


grand = Counter()
print('| Project | Plausible components (RDT, own props) | Found by Caliper | Recall | Props reported |')
print('| --- | ---: | ---: | ---: | ---: |')
shape_by_project = {}
for n in names:
    rdt = json.load(open(f'{res}/{n}.rdt.dump.json'))
    raw = open(f'{res}/{n}.caliper.dump.json').read()
    cal = json.loads(raw[raw.index('{'):])['components']
    by_file = defaultdict(list)
    for c in cal.values():
        by_file[c['filePath']].append((norm(c['displayName']), set(c['props'])))
    tot = hit = ptot = phit = 0
    shapes = Counter()
    for comp in rdt:
        if not plausible(comp['name']):
            continue
        mine = {p for p, v in comp['props'].items() if ('bench-inputs/' + n + '/') in v['parent'] and '/node_modules/' not in v['parent']}
        if not mine:
            continue
        tot += 1
        ptot += len(mine)
        matched = None
        for nm, props in by_file.get(comp['file'], []):
            if nm == norm(comp['name']) or len(mine & props) >= max(1, len(mine) // 2):
                matched = props
                break
        if matched is None:
            try:
                shapes[classify(open(comp['file']).read(), comp['name'])] += 1
            except Exception:
                pass
            continue
        hit += 1
        phit += len(mine & matched)
