30	#[cfg(test)]
31	pub(crate) fn follow_reexports_call_count() -> usize {
32	    FOLLOW_REEXPORTS_CALLS.load(std::sync::atomic::Ordering::Relaxed)
33	}
34	
35	/// Resolve `name` to its canonical `(file_path, name)` pair.
36	/// Returns `None` if `name` is a local declaration (not imported).
37	pub(super) fn resolve_to_canonical(
38	    name: &str,
39	    consuming_file: &Utf8Path,
40	    ctx: &ResolutionContext,
41	    diagnostics: &mut Vec<Diagnostic>,
42	) -> Option<(Utf8PathBuf, String)> {
43	    if let Some(import_ref) = ctx.import_map.find_import(consuming_file, name) {
44	        let resolved_file = resolve_import_specifier(&import_ref.specifier, consuming_file, ctx, diagnostics)?;
45	        let canonical_name = import_ref.exported_name.to_string();
46	        let mut visited = FxHashSet::default();
47	        return Some(follow_reexports(resolved_file, canonical_name, ctx, diagnostics, &mut visited, 0));
48	    }
49	
50	    // Namespace-import member access: `import * as React from "react"` then a
51	    // reference to `React.DependencyList`. `find_import` only tracks the
52	    // namespace binding itself ("React", with `exported_name == "*"`) — a
53	    // literal dotted name like "React.DependencyList" is never itself a
54	    // binding, so the lookup above always misses it. Split off the namespace
55	    // prefix and route the member name through the namespace's own import
56	    // specifier instead.
57	    let (namespace, member) = name.split_once('.')?;
58	    let namespace_ref = ctx.import_map.find_import(consuming_file, namespace)?;
59	    if namespace_ref.exported_name != "*" {
60	        return None;
61	    }
62	    let resolved_file = resolve_import_specifier(&namespace_ref.specifier, consuming_file, ctx, diagnostics)?;
63	    let mut visited = FxHashSet::default();
64	    Some(follow_reexports(resolved_file, member.to_string(), ctx, diagnostics, &mut visited, 0))
65	}
66	
67	/// A directly-imported name may land on a barrel file (`export { X } from
68	/// './x'` or `export * from './x'`) that doesn't declare `name` itself —
69	/// ubiquitous in real component libraries' `index.ts` files. Follow the
70	/// re-export chain until we reach a file that actually declares `name`, or
71	/// run out of chain to follow — in which case the original (barrel_file,
72	/// name) is returned unchanged, so the caller's existing "cannot resolve"
73	/// diagnostic still fires exactly as it did before this existed.
74	fn follow_reexports(
75	    file: Utf8PathBuf,
76	    name: String,
77	    ctx: &ResolutionContext,
78	    diagnostics: &mut Vec<Diagnostic>,
79	    visited: &mut FxHashSet<(Utf8PathBuf, CompactString)>,
80	    depth: u8,
81	) -> (Utf8PathBuf, String) {
82	    #[cfg(test)]
83	    FOLLOW_REEXPORTS_CALLS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
84	
85	    if depth >= MAX_REEXPORT_DEPTH || ctx.named_types.is_declared_at(&file, &name) {
86	        return (file, name);
87	    }
88	    // Real barrels commonly share descendants (several sub-barrels wildcarding
89	    // the same underlying `types.ts`, say) — without this, re-exploring an
90	    // already-visited (file, name) pair from a different parent multiplies out
91	    // to branching_factor^depth calls instead of one call per graph node. This
92	    // also subsumes cycle detection: a cycle revisits a pair by definition.
93	    if !visited.insert((file.clone(), CompactString::from(name.as_str()))) {
94	        return (file, name);
95	    }
96	    match ctx.import_map.resolve_reexport_chain(&file, &name, &ctx.global) {
97	        Some(ReExportStep::Named { source_specifier, source_name }) => {
98	            let Some(next_file) = resolve_import_specifier(&source_specifier, &file, ctx, diagnostics) else {
99	                return (file, name);
100	            };
101	            follow_reexports(next_file, source_name, ctx, diagnostics, visited, depth + 1)
102	        }
103	        Some(ReExportStep::Wildcards(specifiers)) => {
104	            for specifier in &specifiers {
105	                let Some(candidate_file) = resolve_import_specifier(specifier, &file, ctx, diagnostics) else {
106	                    continue;
107	                };
