import re, pathlib, subprocess

root = pathlib.Path('/Users/gabe/Projects/caliper/.claude/worktrees/release-0.2.0/crates')
fields = ['src_dirs', 'exclude_patterns', 'exclude_prefixes', 'react_version', 'cross_package', 'pandacss_outdir',
          'variant_functions', 'html_attributes', 'tsconfig_path', 'extra_paths', 'known_type_overrides',
          'extra_builtins', 'vanilla_extract', 'cache_dir', 'resolve_complex_types']
files = [p for p in root.rglob('*.rs') if '/target/' not in str(p)]


def prod(p):
    s = p.read_text()
    if p.name == 'tests.rs' or '/tests/' in str(p):
        return ''
    i = s.find('#[cfg(test)]')
    return s if i < 0 else s[:i]


texts = {p: prod(p) for p in files}
for f in fields:
    reads = []
    for p, t in texts.items():
        for m in re.finditer(r'(\.|\b)' + f + r'\b', t):
            line = t[:m.start()].count('\n') + 1
            ln = t.split('\n')[line - 1]
            if re.search(r'pub ' + f + r'\s*:', ln) or re.search(r'^\s*' + f + r'\s*:', ln) or ln.strip().startswith('//'):
                continue
            reads.append(f'{p.relative_to(root)}:{line}')
    print(f'{f:22s} {len(reads):3d}  {reads[:4]}')

