        // rcu's return value is the PRE-swap value (arc-swap's compare_and_swap
        // convention), not the value the closure just produced — the closure's
        // result must be re-read via load_full() to see the post-update state.
        self.global.rcu(|old| {
            let mut g = (**old).clone();
