import json, re, sys
from collections import Counter, defaultdict

base = '/private/tmp/claude-501/-Users-gabe-Projects-caliper/ba6a68d6-c702-4382-ab2f-60cd0f6af675/scratchpad/recall-results'
proj = sys.argv[1] if len(sys.argv) > 1 else 'mantine'


def clean(n):
    return re.sub(r' \(.*\)$', '', n)


def norm(n):
    n = clean(n).split('/')[-1].split('.')[-1]
    return re.sub(r'[^a-z0-9]', '', n.lower())


raw = open(f'{base}/{proj}.caliper.dump.json').read()
cal = json.loads(raw[raw.index('{'):])['components']
by_file = defaultdict(list)
for c in cal.values():
    by_file[c['filePath']].append((norm(c['displayName']), set(c['props'])))

missing = Counter()
per_comp = []
for comp in json.load(open(f'{base}/{proj}.rdt.dump.json')):
    mine = {p for p, v in comp['props'].items() if f'bench-inputs/{proj}/' in v['parent'] and '/node_modules/' not in v['parent']}
    if not mine:
        continue
    match = None
    for nm, props in by_file.get(comp['file'], []):
        if nm == norm(comp['name']) or len(mine & props) >= max(1, len(mine) // 2):
            match = props
            break
    if match is None:
        continue
    gone = mine - match
    if gone:
        per_comp.append((len(gone), comp['name'], comp['file'].split(proj + '/')[-1], sorted(gone)[:6]))
    for g in gone:
        missing[g] += 1
print('components with missing props:', len(per_comp))
print('most common missing props:', missing.most_common(12))
for row in sorted(per_comp, reverse=True)[:8]:
    print(row)

