"""Components present in binary A's output but not B's, with B's diagnostic for each. Usage: diffcomps.py A B project"""
import json, subprocess, sys

A, B, proj = sys.argv[1:4]
IN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'
RES = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-results'


def run(b):
    return json.loads(subprocess.run([b, 'extract', '--src', f'{IN}/{proj}', '--json'], capture_output=True, text=True).stdout)


a, b = run(A), run(B)
ka = {(c['filePath'], c['displayName']) for c in a['components'].values()}
kb = {(c['filePath'], c['displayName']) for c in b['components'].values()}
rdt = {(c['file'], c['name'].split('.')[-1]) for c in json.load(open(f'{RES}/{proj}.rdt.dump.json'))}
for f, n in sorted(ka - kb):
    short = n.split('/')[-1]
    why = next((d['message'] for d in b['diagnostics'] if d.get('file') == f and f"'{short}'" in d['message']), '(no diagnostic)')
    print(f"{'RDT' if (f, short) in rdt else '   '} {n:38s} {f.split(proj + '/')[-1][:60]:60s} {why[:130]}")
print('gained:', sorted(n for _, n in kb - ka)[:20])

