27	    depth: u8,
28	) -> ResolvedChain {
29	    if depth > MAX_DEPTH {
30	        let diag = super::max_depth_diagnostic(&format!("type '{}'", type_name), consuming_file);
31	        return ResolvedChain::give_up(type_name.to_owned(), Some(diag), state);
32	    }
33	
34	    // Cycle detection — scoped by file so same type name in different files is OK.
35	    // Must include type_args: distinct instantiations of the same generic alias
36	    // (e.g. `Partial<RowHeights>` vs `Partial<ColumnWidths>` in the same interface's
37	    // extends list) are not the same visit and must not collide on the bare name alone.
38	    let visit_key: CompactString = format!("{}:{}<{}>", consuming_file, type_name, type_args.join(",")).into();
39	    if !state.visited.insert(visit_key) {
40	        return ResolvedChain::give_up(
41	            type_name.to_owned(),
