108	// ─── Incremental watch types ──────────────────────────────────────────────────
109	
110	/// Result of processing a single file change in watch mode.
111	#[derive(Serialize)]
112	#[serde(rename_all = "camelCase")]
113	pub struct IncrementalUpdate {
114	    pub updated_components: Vec<ComponentEntry>,
115	    pub affected_files: Vec<Utf8PathBuf>,
116	    pub diagnostics: Vec<Diagnostic>,
117	    pub duration_ms: u64,
118	}
119	
120	/// Reverse dependency graph: file → list of files that import from it.
121	/// Built once from GlobalSourceData; used by WatchSession for BFS propagation.
122	pub struct ReverseDeps {
123	    pub(super) inner: FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>>,
124	}
125	
126	impl ReverseDeps {
127	    /// Build from a fully-merged GlobalSourceData.
128	    pub fn build(global: &GlobalSourceData) -> Self {
129	        let mut inner: FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>> = Default::default();
130	
131	        for (consumer_file, imports) in &global.import_map {
132	            for import in imports {
133	                // Only chase relative imports — package imports can't be naively reversed.
134	                if import.specifier.starts_with('.') {
135	                    if let Some(parent) = consumer_file.parent() {
136	                        let target = parent.join(&import.specifier);
137	                        // Approximate extension normalization without I/O.
138	                        for ext in &[".ts", ".tsx", "/index.ts", "/index.tsx"] {
139	                            let candidate = Utf8PathBuf::from(format!("{}{}", target, ext));
140	                            inner.entry(candidate).or_default().push(consumer_file.clone());
141	                        }
142	                    }
143	                }
144	            }
145	        }
146	
147	        Self { inner }
148	    }
149	
150	    /// BFS: collect all files transitively affected by a change to `changed`.
151	    pub fn affected(&self, changed: &Utf8Path) -> FxHashSet<Utf8PathBuf> {
152	        let mut visited: FxHashSet<Utf8PathBuf> = Default::default();
153	        let mut queue: VecDeque<Utf8PathBuf> = VecDeque::new();
154	        queue.push_back(changed.to_owned());
155	
156	        while let Some(file) = queue.pop_front() {
157	            if visited.insert(file.clone()) {
158	                for dep in self.inner.get(&file).into_iter().flatten() {
159	                    queue.push_back(dep.clone());
160	                }
161	            }
162	        }
163	
164	        visited
165	    }
