366	    // cloning here just to immediately re-borrow deep-cloned every mapping's
367	    // Strings/Vecs/param_defaults map for no reason, once per component.
368	    let mappings: Vec<&ComponentMapping> = global
369	        .component_mappings
370	        .iter()
371	        .filter(|m| !should_skip(&m.component_name, &options.exclude_prefixes))
372	        .collect();
