379	    let mut seen_names: std::collections::HashMap<String, u32> = Default::default();
380	
381	    for (entry, diags) in results {
382	        let base_name = entry.display_name.clone();
383	        let count = seen_names.entry(base_name.clone()).or_insert(0);
384	        *count += 1;
385	
386	        let key = if *count == 1 {
387	            base_name
388	        } else {
