74	/// The mapping identities of `global`, in output order: by file, then by position in the file.
75	fn component_ids<'g>(
76	    global: &'g GlobalSourceData,
77	    options: &PipelineOptions,
78	) -> Vec<(ComponentId, &'g ComponentMapping)> {
79	    let mut ordinals: FxHashMap<(&Utf8Path, &str), u32> = FxHashMap::default();
80	    let mut ids: Vec<(ComponentId, &ComponentMapping)> = global
81	        .component_mappings
82	        .iter()
83	        .filter(|m| !should_skip(&m.component_name, &options.exclude_prefixes))
84	        .map(|m| {
85	            let ordinal = ordinals.entry((m.file_path.as_path(), m.component_name.as_str())).or_insert(0);
86	            let id = ComponentId { file: m.file_path.clone(), name: m.component_name.clone(), ordinal: *ordinal };
87	            *ordinal += 1;
88	            (id, m)
89	        })
90	        .collect();
91	    ids.sort_by(|(a, ma), (b, mb)| (&a.file, ma.span_start, a.ordinal).cmp(&(&b.file, mb.span_start, b.ordinal)));
92	    ids
93	}
