95	fn resolve_all(
96	    mappings: &[(ComponentId, &ComponentMapping)],
97	    ctx: &ResolutionContext,
98	) -> FxHashMap<ComponentId, Resolved> {
99	    let borrowed: Vec<&ComponentMapping> = mappings.iter().map(|(_, m)| *m).collect();
100	    resolve_guarded(&borrowed, ctx)
101	        .into_iter()
102	        .zip(mappings)
103	        .map(|((entry, diagnostics, depends_on), (id, _))| (id.clone(), Resolved { entry, diagnostics, depends_on }))
104	        .collect()
105	}
