107	impl Revision {
108	    /// Discover, parse, merge, resolve and assemble every source file.
109	    pub(crate) fn cold(options: &PipelineOptions, id: u64) -> Revision {
110	        let start = Instant::now();
111	        let mut head_diagnostics = source_dir_diagnostics(options);
112	
113	        // Load the DTS parse-result cache (silently empty if missing/stale).
114	        let cache = Arc::new(DtsCache::load_from_disk(options.cache_dir.as_deref()));
115	
116	        let (src_files, discover_diagnostics) = discover_files(&options.src_dirs, &options.exclude_patterns);
117	        head_diagnostics.extend(discover_diagnostics);
118	        let files_parsed = src_files.len() as u32;
119	
120	        let cache_hits = AtomicU32::new(0);
121	        // The whole closure body is wrapped in `contain_panic` so one file's parse panicking degrades to a per-file
122	        // diagnostic instead of poisoning the `.collect()` and crashing the whole extraction run.
123	        let parsed: Vec<(Utf8PathBuf, SourceData, Option<Diagnostic>)> = src_files
124	            .par_iter()
125	            .map(|path| {
126	                let label = format!("parse:{path}");
127	                crate::panic_guard::contain_panic(&label, || {
128	                    #[cfg(test)]
129	                    if path.file_name() == Some(super::PARSE_PANIC_TEST_SENTINEL) {
130	                        panic!("simulated parse-phase panic (test-only sentinel)");
131	                    }
132	                    let (data, io_diag, hit) = parse_source_file(path, &cache);
133	                    if hit {
134	                        cache_hits.fetch_add(1, Ordering::Relaxed);
135	                    }
136	                    (path.clone(), data, io_diag)
137	                })
138	                .unwrap_or_else(|diag| (path.clone(), SourceData::default(), Some(diag)))
139	            })
140	            .collect();
141	
142	        let mut global = GlobalSourceData::default();
143	        let mut file_diagnostics: BTreeMap<Utf8PathBuf, Vec<Diagnostic>> = BTreeMap::new();
144	        for (path, mut data, io_diag) in parsed {
145	            let mut diags: Vec<Diagnostic> = io_diag.into_iter().collect();
146	            diags.append(&mut data.diagnostics);
147	            diags.extend(options.plugins.run_on_file_extracted(&path, &mut data));
148	            if !diags.is_empty() {
149	                file_diagnostics.insert(path.clone(), diags);
150	            }
151	            global.merge(&path, data);
152	        }
153	
154	        let mut lib_diagnostics = Vec::new();
155	        // Full HTML attribute mode needs @types/react's real interfaces merged before resolution, so the resolver can
156	        // look them up like any other interface instead of only recording an InheritedLayer.
157	        if options.html_attributes == HtmlAttributeMode::Full {
158	            let from_dir = canonicalize_first_src_dir(&options.src_dirs).unwrap_or_else(|| Utf8PathBuf::from("."));
159	            match crate::resolver::resolve_package_dts_path(&from_dir, "react") {
160	                Some(react_dts_path) => {
161	                    let react_dts_path = Utf8PathBuf::from(react_dts_path);
162	                    merge_cached_dts_file(&react_dts_path, &cache, &mut global, &mut lib_diagnostics);
163	                }
164	                None => lib_diagnostics.push(
165	                    Diagnostic::new(
166	                        DiagnosticSeverity::Warning,
167	                        DiagnosticCode::MissingTypeLibrary,
168	                        "HtmlAttributeMode::Full requested but @types/react could not be resolved",
169	                    )
170	                    .with_help("Check that @types/react is installed. Falling back to curated attributes."),
171	                ),
172	            }
173	        }
174	        // Ambient globals (Date, Element, ...) live in TS's lib files and are never imported, so merge them in every
175	        // mode. An install missing a lib file (TS 7 without its platform package) is reported here.
176	        if let Some(from_dir) = canonicalize_first_src_dir(&options.src_dirs) {
177	            let libs = crate::resolver::resolve_ts_lib_paths(&from_dir);
178	            lib_diagnostics.extend(libs.diagnostic);
179	            for lib_path in libs.paths {
180	                merge_cached_dts_file(&Utf8PathBuf::from(lib_path), &cache, &mut global, &mut lib_diagnostics);
181	            }
182	        }
183	
184	        let global = Arc::new(global);
185	        let named_types = Arc::new(NamedTypeIndex::build(&global));
186	        let ambient_global_files = crate::resolver::compute_ambient_global_files(options);
187	        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
188	            global.clone(),
189	            options,
190	            ambient_global_files.clone(),
191	            named_types.clone(),
192	        );
193	        let resolved = resolve_all(&component_ids(&global, options), &ctx);
194	
195	        // Arc::try_unwrap succeeds because all rayon workers have finished.
196	        let tail_diagnostics: Vec<Diagnostic> = match Arc::try_unwrap(cache) {
197	            Ok(c) => c.save_to_disk(),
198	            Err(arc) => arc.save_to_disk(),
199	        }
200	        .into_iter()
201	        .collect();
202	
203	        let mut revision = Revision {
204	            id,
205	            global,
206	            named_types,
207	            ambient_global_files,
208	            head_diagnostics,
209	            file_diagnostics,
210	            lib_diagnostics,
211	            tail_diagnostics,
212	            resolved,
213	            files_parsed,
214	            dts_cache_hits: cache_hits.load(Ordering::Relaxed),
215	            duration_ms: 0,
216	            output: Arc::new(empty_output()),
217	            keys: FxHashMap::default(),
218	        };
219	        revision.duration_ms = start.elapsed().as_millis() as u64;
220	        revision.assemble(options);
221	        revision
222	    }
223	
224	    /// The revision after `changed` was edited, created or deleted, and the delta from this one. `None` when the path
225	    /// is not a source file of this project (outside every source directory, excluded, or not TypeScript).
226	    pub(crate) fn next(&self, options: &PipelineOptions, changed: &Utf8Path) -> Option<(Revision, IncrementalUpdate)> {
227	        if !is_source_file(changed, &options.src_dirs, &options.exclude_patterns) {
228	            return None;
229	        }
230	        let start = Instant::now();
231	
232	        let mut global = (*self.global).clone();
233	        let mut named_types = (*self.named_types).clone();
234	        let mut file_diagnostics = self.file_diagnostics.clone();
235	        global.remove_file(changed);
236	        named_types.remove_file(changed);
237	        file_diagnostics.remove(changed);
238	
239	        match std::fs::read_to_string(changed) {
240	            // Deleted: its declarations and diagnostics leave with it.
241	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
242	            Err(e) => {
243	                // Unreadable for another reason (permissions, an editor's partial write): keep what it last declared.
244	                let previous = self.global_data_for(changed);
245	                named_types.merge_file(&previous);
246	                global.merge(changed, previous);
247	                file_diagnostics.insert(changed.to_owned(), vec![Diagnostic::io_read_error(changed, &e)]);
248	            }
249	            Ok(source) => {
250	                let mut data = crate::extractor::parse_file(changed, &source);
251	                let mut diags = std::mem::take(&mut data.diagnostics);
252	                diags.extend(options.plugins.run_on_file_extracted(changed, &mut data));
253	                if !diags.is_empty() {
254	                    file_diagnostics.insert(changed.to_owned(), diags);
255	                }
256	                named_types.merge_file(&data);
257	                global.merge(changed, data);
258	            }
259	        }
260	
261	        let global = Arc::new(global);
262	        let named_types = Arc::new(named_types);
263	        let ids = component_ids(&global, options);
264	        let (stale, kept): (Vec<_>, Vec<_>) = ids.into_iter().partition(|(id, _)| match self.resolved.get(id) {
265	            None => true,
266	            Some(previous) => id.file == changed || previous.depends_on.contains(changed) || previous.incomplete(),
267	        });
268	        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
269	            global.clone(),
270	            options,
271	            self.ambient_global_files.clone(),
272	            named_types.clone(),
273	        );
274	        let fresh = resolve_all(&stale, &ctx);
275	        let mut resolved: FxHashMap<ComponentId, Resolved> =
276	            kept.into_iter().filter_map(|(id, _)| self.resolved.get(&id).map(|r| (id, r.clone()))).collect();
277	        let fresh_ids: Vec<ComponentId> = fresh.keys().cloned().collect();
278	        resolved.extend(fresh);
279	
280	        let mut next = Revision {
281	            id: self.id + 1,
282	            global,
283	            named_types,
284	            ambient_global_files: self.ambient_global_files.clone(),
285	            head_diagnostics: self.head_diagnostics.clone(),
286	            file_diagnostics,
287	            lib_diagnostics: self.lib_diagnostics.clone(),
288	            tail_diagnostics: self.tail_diagnostics.clone(),
289	            resolved,
290	            files_parsed: self.files_parsed,
291	            dts_cache_hits: self.dts_cache_hits,
292	            duration_ms: self.duration_ms,
293	            output: Arc::new(empty_output()),
294	            keys: FxHashMap::default(),
295	        };
296	        next.assemble(options);
297	
298	        let updated_components: Vec<(String, ComponentEntry)> = fresh_ids
299	            .iter()
300	            .filter_map(|id| {
301	                Some((next.keys.get(id)?.clone(), next.output.components.get(next.keys.get(id)?)?.clone()))
302	            })
303	            .collect();
304	        let removed_keys: Vec<String> =
305	            self.output.components.keys().filter(|key| !next.output.components.contains_key(*key)).cloned().collect();
306	        let mut affected_files: Vec<Utf8PathBuf> = fresh_ids.iter().map(|id| id.file.clone()).collect();
307	        affected_files.sort();
308	        affected_files.dedup();
309	        let mut diagnostics: Vec<Diagnostic> = next.file_diagnostics.get(changed).cloned().unwrap_or_default();
310	        for id in &fresh_ids {
311	            if let Some(r) = next.resolved.get(id) {
312	                diagnostics.extend(r.diagnostics.iter().cloned());
313	            }
314	        }
315	        let update = IncrementalUpdate {
316	            revision: next.id,
317	            updated_components: updated_components.iter().map(|(_, entry)| entry.clone()).collect(),
318	            updated_keys: updated_components.into_iter().map(|(key, _)| key).collect(),
319	            removed_keys,
320	            affected_files,
321	            diagnostics,
322	            duration_ms: start.elapsed().as_millis() as u64,
323	        };
324	        Some((next, update))
325	    }
326	
327	    /// What `file` last contributed to `global`, rebuilt from the merged maps. Used only to keep an unreadable file's
328	    /// declarations in place.
329	    fn global_data_for(&self, file: &Utf8Path) -> SourceData {
330	        let prefix = format!("{file}:");
331	        let pick = |key: &String| key.starts_with(&prefix);
332	        SourceData {
333	            interfaces: self
334	                .global
335	                .interfaces
336	                .iter()
337	                .filter(|(k, _)| pick(k))
338	                .map(|(k, v)| (k.clone(), v.clone()))
339	                .collect(),
340	            type_aliases: self
341	                .global
342	                .type_aliases
343	                .iter()
344	                .filter(|(k, _)| pick(k))
345	                .map(|(k, v)| (k.clone(), v.clone()))
346	                .collect(),
347	            type_alias_params: self
348	                .global
349	                .type_alias_params
350	                .iter()
351	                .filter(|(k, _)| pick(k))
352	                .map(|(k, v)| (k.clone(), v.clone()))
353	                .collect(),
354	            interface_type_params: self
355	                .global
356	                .interface_type_params
357	                .iter()
358	                .filter(|(k, _)| pick(k))
359	                .map(|(k, v)| (k.clone(), v.clone()))
360	                .collect(),
361	            enums: self.global.enums.iter().filter(|(k, _)| pick(k)).map(|(k, v)| (k.clone(), v.clone())).collect(),
362	            const_arrays: self
363	                .global
364	                .const_arrays
365	                .iter()
366	                .filter(|(k, _)| pick(k))
367	                .map(|(k, v)| (k.clone(), v.clone()))
368	                .collect(),
369	            component_mappings: self
370	                .global
371	                .component_mappings
372	                .iter()
373	                .filter(|m| m.file_path == file)
374	                .cloned()
375	                .collect(),
376	            imports: self.global.import_map.get(file).cloned().unwrap_or_default(),
377	            exports: self.global.re_export_map.get(file).cloned().unwrap_or_default(),
378	            diagnostics: Vec::new(),
379	        }
380	    }
381	
382	    /// Build the public output from the revision: components keyed with the same disambiguation rule everywhere,
383	    /// plugin hooks applied, diagnostics in a stable order, public enums.
384	    fn assemble(&mut self, options: &PipelineOptions) {
385	        let mut diagnostics: Vec<Diagnostic> = self.head_diagnostics.clone();
386	        for diags in self.file_diagnostics.values() {
387	            diagnostics.extend(diags.iter().cloned());
388	        }
389	        diagnostics.extend(self.lib_diagnostics.iter().cloned());
390	
391	        let mut components = BTreeMap::new();
392	        let mut keys = FxHashMap::default();
393	        let mut seen_names: FxHashMap<String, u32> = FxHashMap::default();
394	        for (id, _) in component_ids(&self.global, options) {
395	            let Some(resolved) = self.resolved.get(&id) else { continue };
396	            let mut entry = resolved.entry.clone();
397	            let base_name = entry.display_name.clone();
398	            let count = seen_names.entry(base_name.clone()).or_insert(0);
399	            *count += 1;
400	            // The first occurrence of a name keeps it bare; later ones take their file path, which is unique per file.
401	            let key = if *count == 1 { base_name } else { format!("{} ({})", base_name, entry.file_path) };
402	            diagnostics.extend(options.plugins.run_on_component_resolved(&mut entry));
403	            let new_file_path = entry.file_path.clone();
404	            if let Some(previous) = components.insert(key.clone(), entry) {
405	                diagnostics.push(
406	                    Diagnostic::new(
407	                        DiagnosticSeverity::Warning,
408	                        DiagnosticCode::ComponentKeyCollision,
409	                        format!(
410	                            "Duplicate component key '{key}' — colliding file paths: previously '{}', now '{}'",
411	                            previous.file_path, new_file_path
412	                        ),
413	                    )
414	                    .with_file(new_file_path.to_string())
415	                    .with_help(
416	                        "Two resolved components produced the same display name and disambiguation key — only the \
417	                         later one is kept in the output. Check for overlapping src_dirs or a genuine duplicate \
418	                         declaration.",
419	                    ),

