20	/// Builds the options, prints the banner, and runs the first extraction. Key shortcuts are advertised only when
21	/// `interactive`.
22	fn start_session(
23	    args: &crate::WatchArgs,
24	    quiet: bool,
25	    interactive: bool,
26	    config_path: Option<&str>,
27	) -> Result<(PipelineOptions, Arc<WatchSession>, Arc<AtomicI32>)> {
28	    use indicatif::{ProgressBar, ProgressStyle};
29	    use owo_colors::OwoColorize;
30	
31	    let options = build_options(BuildOptionsArgs {
32	        src: &args.src,
33	        cache_dir: None,
34	        html_attributes: None,
35	        config_path,
36	        extra_builtins: &[],
37	    })?;
38	
39	    if !quiet {
40	        println!();
41	        let hint = if interactive { "  (press q to quit, r to re-extract)" } else { "" };
42	        println!(
43	            "  {}  {} watching {}{}",
44	            "⚡".yellow(),
45	            "caliper-docgen".bold(),
46	            options.src_dirs.iter().map(|d| d.to_string()).collect::<Vec<_>>().join(", ").cyan(),
47	            hint.dimmed()
48	        );
49	        println!();
50	    }
51	
52	    let pb = if !quiet {
53	        let pb = ProgressBar::new_spinner();
54	        pb.set_style(ProgressStyle::default_spinner().template("{spinner:.cyan} {msg}").into_diagnostic()?);
55	        pb.set_message("Extracting...");
56	        pb.enable_steady_tick(std::time::Duration::from_millis(80));
57	        Some(pb)
58	    } else {
59	        None
60	    };
61	
62	    let session = Arc::new(WatchSession::new(options.clone()));
63	    let first = session.initialize();
64	
65	    if let Some(pb) = pb {
66	        pb.finish_and_clear();
67	    }
68	    if !quiet {
69	        print_summary(&first, quiet);
70	        print_diagnostics(&first.diagnostics);
71	    }
72	
73	    let exit_code = Arc::new(AtomicI32::new(watch_exit_code(&first)));
74	    Ok((options, session, exit_code))
75	}
