77	/// `Some(exit code)` when `key` quits. Raw mode turns off ISIG, so Ctrl-C arrives here as a key, not SIGINT. `r` only
78	/// refreshes the tracked exit code: past its first call `initialize()` returns the current snapshot.
79	fn handle_key(key: KeyEvent, session: &WatchSession, exit_code: &AtomicI32) -> Option<i32> {
80	    match key.code {
81	        KeyCode::Char('q') => Some(exit_code.load(Ordering::Relaxed)),
82	        KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => Some(exit_code.load(Ordering::Relaxed)),
83	        KeyCode::Char('r') => {
84	            exit_code.store(watch_exit_code(&session.initialize()), Ordering::Relaxed);
85	            None
86	        }
87	        _ => None,
88	    }
89	}
