91	/// Feeds key presses to `on_key` until it returns an exit code; `Err` once input can no longer be read.
92	fn read_keys(
93	    mut next: impl FnMut() -> std::io::Result<Event>,
94	    mut on_key: impl FnMut(KeyEvent) -> Option<i32>,
95	) -> std::io::Result<i32> {
96	    loop {
97	        if let Event::Key(key) = next()? {
98	            if let Some(code) = on_key(key) {
99	                return Ok(code);
100	            }
101	        }
102	    }
103	}
