      const p = watchBuild()
      await (p.buildStart as Function).call(pluginContext())

      await (p.watchChange as Function)('/project/src/Button.tsx', { event: 'update' })
      await (p.watchChange as Function)('/project/src/notes.md', { event: 'update' })
      await (p.buildStart as Function).call(pluginContext())

