#[test]
fn identical_diagnostics_from_many_components_are_reported_once_listing_them() {
    let tmp = TempDir::new().unwrap();
    for name in ["Button", "Card"] {
        write_file(
            &tmp,
            &format!("{name}.tsx"),
            &format!("import type {{ Shared }} from './missing';\nexport function {name}(props: Shared) {{ return null; }}\n"),
        );
    }
    let options = PipelineOptions {
        src_dirs: vec![Utf8PathBuf::from_path_buf(tmp.path().canonicalize().unwrap()).unwrap()],
        cache_dir: Some(Utf8PathBuf::from_path_buf(tmp.path().join("cache")).unwrap()),
        ..Default::default()
    };

    let output = extract(&options);

    let summary: Vec<(String, Vec<String>)> = output
        .diagnostics
        .iter()
        .map(|d| (d.file.as_deref().unwrap_or("").rsplit('/').next().unwrap_or("").to_owned(), d.affects.clone()))
        .collect();
    // One unresolvable import per consuming file, each attributed to its component; the unresolved type is reported
    // once per file too.
    assert_eq!(
        output.diagnostics.iter().map(|d| d.message.matches("'./missing'").count()).sum::<usize>(),
        2,
        "{:#?}",
        output.diagnostics
    );
    assert!(summary.iter().all(|(_, affects)| affects.len() == 1), "{summary:?}");
    let unique: std::collections::HashSet<&Diagnostic> = output.diagnostics.iter().collect();
    assert_eq!(unique.len(), output.diagnostics.len(), "no diagnostic is reported twice");
}
EOF
cargo test -p caliper-docgen-core --lib identical_diagnostics 2>&1 | grep -E "test result|panicked" -A30 | head -50

