1	//! Pins the on-disk shape of `SourceData`. The cache is positional MessagePack (ADR 0003), so reordering a field or
2	//! adding a variant silently corrupts old entries unless `CACHE_SCHEMA_VERSION` moves. A change here that is not
3	//! accompanied by a version bump is the bug this test exists to catch.
4	
5	use camino::Utf8Path;
6	
7	use super::CACHE_SCHEMA_VERSION;
8	use crate::extractor::parse_file;
9	use crate::types::collected::SourceData;
10	
11	const FIXTURE: &str = r#"
12	import React, { forwardRef } from "react";
13	import type { Base } from "./base";
14	
15	/** A size scale. */
16	export const SIZES = ["sm", "md", "lg"] as const;
17	
18	export enum Tone {
19	  Quiet = "quiet",
20	  Loud = "loud",
21	}
22	
23	type Pick2<T, K extends keyof T> = { [P in K]: T[P] };
24	
25	/** Button props. */
26	export interface ButtonProps<TValue = string> extends Base {
27	  /** Visual tone. @default "quiet" */
28	  tone?: Tone;
29	  size: (typeof SIZES)[number];
30	  value?: TValue;
31	  onPress?: (event: MouseEvent) => void;
32	}
33	
34	export type Alias = Pick2<ButtonProps, "tone"> & { extra?: number };
35	
36	export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(props, ref) {
37	  return <button ref={ref} />;
38	});
39	
40	export function Card(props: Alias) {
41	  return <div />;
42	}
43	
44	const Opaque = makeThing();
45	"#;
46	
47	fn fixture() -> SourceData {
48	    parse_file(Utf8Path::new("/golden/button.tsx"), FIXTURE)
49	}
50	
51	#[test]
52	fn fixture_populates_every_source_data_field() {
53	    let SourceData {
54	        interfaces,
55	        type_aliases,
56	        type_alias_params,
57	        interface_type_params,
58	        enums,
59	        const_arrays,
60	        component_mappings,
61	        imports,
62	        exports,
63	        diagnostics,
64	    } = fixture();
65	    let fields = [
66	        ("interfaces", interfaces.is_empty()),
67	        ("type_aliases", type_aliases.is_empty()),
68	        ("type_alias_params", type_alias_params.is_empty()),
69	        ("interface_type_params", interface_type_params.is_empty()),
70	        ("enums", enums.is_empty()),
71	        ("const_arrays", const_arrays.is_empty()),
72	        ("component_mappings", component_mappings.is_empty()),
73	        ("imports", imports.is_empty()),
74	        ("exports", exports.is_empty()),
75	        ("diagnostics", diagnostics.is_empty()),
76	    ];
77	    let empty: Vec<&str> = fields.iter().filter(|(_, is_empty)| *is_empty).map(|(name, _)| *name).collect();
78	    assert_eq!(empty, Vec::<&str>::new(), "extend FIXTURE so the golden bytes cover these fields");
79	}
80	
81	#[test]
82	fn source_data_bytes_are_stable_for_the_current_schema_version() {
83	    let bytes = rmp_serde::to_vec(&fixture()).unwrap();
84	    let hex: String = bytes.iter().map(|b| format!("{b:02x}")).collect();
85	    insta::assert_snapshot!(format!("schema {CACHE_SCHEMA_VERSION}\n{hex}"));
86	}
87	
88	#[test]
89	fn source_data_round_trips_through_msgpack() {
90	    let original = fixture();
91	    let decoded: SourceData = rmp_serde::from_slice(&rmp_serde::to_vec(&original).unwrap()).unwrap();
92	    assert_eq!(serde_json::to_value(&decoded).unwrap(), serde_json::to_value(&original).unwrap());
93	}
94	
95	#[test]
96	fn a_blob_from_the_previous_schema_version_is_rejected() {
97	    let dir = std::env::temp_dir().join(format!("caliper-golden-{}", std::process::id()));
98	    std::fs::create_dir_all(&dir).unwrap();
99	    let cache_dir = camino::Utf8PathBuf::from_path_buf(dir.join("cache")).unwrap();
100	    let source_path = camino::Utf8PathBuf::from_path_buf(dir.join("button.d.ts")).unwrap();
101	    std::fs::write(&source_path, FIXTURE).unwrap();
102	
103	    let writer = super::DtsCache::load_from_disk(Some(&cache_dir));
104	    writer.insert(&source_path, FIXTURE, fixture());
105	    assert!(writer.save_to_disk().is_none());
106	    assert!(super::DtsCache::load_from_disk(Some(&cache_dir)).get(&source_path, FIXTURE).is_some());
107	
108	    // Same data file, manifest rewritten as the previous schema version wrote it.
109	    let previous = serde_json::json!({ "schema": u64::from(CACHE_SCHEMA_VERSION - 1), "entry_count": 1u64 });
110	    std::fs::write(cache_dir.join("manifest.json"), serde_json::to_string(&previous).unwrap()).unwrap();
111	    let reloaded = super::DtsCache::load_from_disk(Some(&cache_dir));
112	    let loaded = reloaded.get(&source_path, FIXTURE).is_some();
113	    std::fs::remove_dir_all(&dir).unwrap();
114	
115	    assert!(!loaded, "entries written under schema {} must not load", CACHE_SCHEMA_VERSION - 1);
116	}
