"""Sample prop-type differences between two binaries on one corpus. Usage: prop_diff.py A B project [n]"""
import collections, json, subprocess, sys

A, B, P = sys.argv[1:4]
N = int(sys.argv[4]) if len(sys.argv) > 4 else 8
IN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'


def run(b):
    return json.loads(subprocess.run([b, 'extract', '--src', f'{IN}/{P}', '--json'], capture_output=True, text=True).stdout)


a, b = run(A), run(B)
changed, kinds, sizes = [], collections.Counter(), []
for name, comp in a['components'].items():
    other = b['components'].get(name)
    if other is None:
        continue
    for prop, pa in comp['props'].items():
        pb = other['props'].get(prop)
        if pb and pa['type'] != pb['type']:
            ta, tb = json.dumps(pa['type']), json.dumps(pb['type'])
            changed.append((name, prop, ta, tb))
            kinds[(pa['type'].get('kind'), pb['type'].get('kind'))] += 1
            sizes.append(len(tb) - len(ta))
print('props changed:', len(changed), 'kind transitions:', kinds.most_common(8))
if sizes:
    sizes.sort()
    print('size delta median', sizes[len(sizes) // 2], 'max', sizes[-1])
seen = set()
for name, prop, ta, tb in changed:
    if prop in seen:
        continue
    seen.add(prop)
    print(f'\n{name}.{prop}\n  A {ta[:300]}\n  B {tb[:300]}')
    if len(seen) >= N:
        break

