import collections, json, subprocess, sys

BIN, P, NAME = sys.argv[1:4]
IN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'
d = json.loads(subprocess.run([BIN, 'extract', '--src', f'{IN}/{P}', '--json'], capture_output=True, text=True).stdout)


def has(t):
    if isinstance(t, dict):
        if t.get('kind') == 'named' and not t.get('args') and t.get('name') == NAME:
            return True
        return any(has(v) for v in t.values())
    if isinstance(t, list):
        return any(has(v) for v in t)
    return False


hits = collections.Counter()
example = {}
for cname, comp in d['components'].items():
    for pname, prop in comp['props'].items():
        if has(prop['type']):
            key = (pname, (prop.get('parent') or {}).get('name'))
            hits[key] += 1
            example.setdefault(key, (cname, json.dumps(prop['type'])[:400]))
for key, n in hits.most_common(6):
    print(n, key, example[key][0])
    print('   ', example[key][1])

