        Some(Body::Block(body)) => {
            let mut own = OwnBody::default();
            own.visit_function_body(body);
            element_locals = std::mem::take(&mut own.element_locals);
            own.calls_hook || own.returns.iter().any(|r| returns_element(r, &element_locals))
        }
