    /// inferred from a function's shape and what it returns; the others are explicit declaration forms.
    pub detected_by: crate::types::DetectionRule,
}''')])

# Real construction sites take the mapping's rule; test and sample literals a fixed one.
REAL = {'crates/core/src/resolver/mod.rs', 'crates/core/src/pipeline/mod.rs'}
for round_ in range(4):
    out = subprocess.run(['cargo', 'build', '--workspace', '--all-targets', '--message-format=json'], cwd=ROOT,
                         capture_output=True, text=True).stdout
    sites = collections.defaultdict(set)
    for line in out.splitlines():
        try:
            m = json.loads(line).get('message') or {}
        except ValueError:
            continue
        if (m.get('code') or {}).get('code') == 'E0063' and 'detected_by' in m.get('message', ''):
            for span in m['spans']:
                if span['is_primary']:
                    sites[span['file_name']].add(span['byte_start'])
    if not sites:
        print('done after', round_)
        break
    for file, starts in sites.items():
        p = ROOT / file
        b = p.read_bytes()
        value = b'mapping.rule' if file in REAL else b'crate::types::DetectionRule::FunctionDeclaration'
        if file.startswith('crates/cli'):
            value = b'caliper_docgen_core::types::DetectionRule::FunctionDeclaration'
        for start in sorted(starts, reverse=True):
            brace = b.index(b'{', start)
            depth, i = 0, brace
            while True:
                c = b[i:i + 1]
                if c == b'{':
                    depth += 1
                elif c == b'}':
                    depth -= 1
                    if depth == 0:
                        break
                i += 1
            before = b[brace + 1:i].rstrip()
            sep = b'' if before.endswith(b',') else b','
            b = b[:brace + 1] + before + sep + b' detected_by: ' + value + b', ' + b[i:]
        p.write_bytes(b)
        print(file, len(starts), value.decode())
subprocess.run(['cargo', 'fmt', '--all'], cwd=ROOT)

