"""Per-rule precision from sample.json and the labelled false positives. Usage: precision_report.py"""
import collections, json

D = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/review/precision'
sample = json.load(open(f'{D}/sample.json'))
# Every sampled id was labelled; these are the ones not labelled `component` (all four batch reports).
NOT_COMPONENT = {78}
UNSURE = set()
per = collections.defaultdict(lambda: [0, 0, 0])
for item in sample:
    row = per[item['rule']]
    row[0] += 1
    if item['id'] in NOT_COMPONENT:
        row[1] += 1
    elif item['id'] in UNSURE:
        row[2] += 1
print('| Rule | Sampled | Not a component | Unsure | Precision |')
print('| --- | ---: | ---: | ---: | ---: |')
for rule, (n, fp, un) in sorted(per.items()):
    print(f'| `{rule}` | {n} | {fp} | {un} | {100 * (n - fp - un) / n:.0f}% |')
for item in sample:
    if item['id'] in NOT_COMPONENT:
        print('FP:', item['rule'], item['corpus'], item['name'], item['file'].split('bench-inputs/')[-1], item['line'])

