"""Classify every type disagreement with RDT into families and count them per corpus. Usage: type_families.py BIN"""
import collections, json, re, subprocess, sys

BIN = sys.argv[1]
IN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'
RES = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-results'
D = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/review/precision'


def norm_name(n):
    n = re.sub(r' \(.*\)$', '', n).split('/')[-1].split('.')[-1]
    return re.sub(r'[^a-z0-9]', '', n.lower())


def tidy(t):
    t = (t or '').replace("'", '"')
    t = re.sub(r';\s*}', ' }', t)
    t = re.sub(r';\s*', '; ', t)
    t = re.sub(r'\?: ([^;{}]+?) \| undefined', r'?: \1', t)
    t = re.sub(r'\bReact\.', '', t)
    t = re.sub(r'\s+', ' ', t).strip()
    if t.startswith('((') and t.endswith(')'):
        t = t[1:-1]
    m = re.fullmatch(r'\((\(.*\) => .*)\)', t)
    if m:
        t = m.group(1)
    if '|' in t and not re.search(r'[(<{\[]', t):
        t = ' | '.join(sorted(p.strip() for p in t.split('|')))
    return t


def family(cal, rdt):
    if tidy(cal) == tidy(rdt):
        return 'formatting only'
    if rdt.strip() in ('any', 'unknown'):
        return 'RDT any/unknown (deps not installed)'
    if re.fullmatch(r'\((e: void)?\) => void', cal) and '=>' in rdt and not rdt.rstrip(')').endswith('=> void'):
        return 'callback return type lost'
    if re.search(r'\) => void$', cal) and re.search(r'=> (?!void)[^=]+\)?$', rdt):
        return 'callback return type lost'
    if re.search(r'\(e: [A-Za-z.]*(EventHandler|Handler)[^)]*\) => void', cal):
        return 'handler type wrapped as a parameter'
    if re.fullmatch(r'[A-Z][\w.]*(<.*>)?(\[\])?', rdt.strip()) and not re.fullmatch(r'[A-Z][\w.]*(<.*>)?(\[\])?', cal.strip()):
        return 'Caliper expanded an alias RDT names'
    if re.fullmatch(r'[A-Z][\w.]*(<.*>)?(\[\])?', cal.strip()) and not re.fullmatch(r'[A-Z][\w.]*(<.*>)?(\[\])?', rdt.strip()):
        return 'Caliper kept a name RDT expanded'
    if 'extends' in cal and '?' in cal:
        return 'conditional type left unevaluated'
    if cal.strip() == 'enum' or rdt.strip() == 'enum':
        return '"enum" placeholder'
    return 'other'


totals = collections.Counter()
per = collections.defaultdict(collections.Counter)
examples = collections.defaultdict(list)
shared = collections.Counter()
for corpus in ['mantine', 'chakra', 'antd', 'shadcn', 'spectrum']:
    cal = json.load(open(f'{D}/{corpus}.caliper.rdt.json'))
    canonical = json.loads(subprocess.run([BIN, 'extract', '--src', f'{IN}/{corpus}', '--json'], capture_output=True,
                                          text=True).stdout)['components']
    by_key = {(canonical[k]['filePath'], norm_name(c['displayName'])): c for k, c in cal.items() if k in canonical}
    for r in json.load(open(f'{RES}/{corpus}.rdt.dump.json')):
        c = by_key.get((r['file'], norm_name(r['name'])))
        if not c:
            continue
        for name in c['props'].keys() & r['props'].keys():
            shared[corpus] += 1
            ct = c['props'][name].get('type', {}).get('name') or ''
            rt = r['props'][name]['type'] or ''
            if ct == rt:
                continue
            f = family(ct, rt)
            per[corpus][f] += 1
            totals[f] += 1
            if len(examples[f]) < 4:
                examples[f].append((corpus, r['name'], name, ct[:90], rt[:90]))

corpora = ['mantine', 'chakra', 'antd', 'shadcn', 'spectrum']
print('| Family | ' + ' | '.join(corpora) + ' | Total |')
print('| --- |' + ' ---: |' * (len(corpora) + 1))
for f, n in totals.most_common():
    print(f'| {f} | ' + ' | '.join(str(per[c][f]) for c in corpora) + f' | {n} |')
print('| props compared | ' + ' | '.join(str(shared[c]) for c in corpora) + f' | {sum(shared.values())} |')
for f, rows in examples.items():
    print('\n#', f)
    for row in rows:
        print('  ', ' | '.join(row))

