"""Size and parse cost of the canonical output as-is, with prop types interned in a table, and with whole props interned."""
import gzip, json, subprocess, sys, time

BIN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/review/caliper-docgen-next'
IN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'


def intern(out, field):
    table, index = [], {}
    for c in out['components'].values():
        for name, p in c['props'].items():
            v = p['type'] if field == 'type' else p
            key = json.dumps(v, sort_keys=True)
            if key not in index:
                index[key] = len(table)
                table.append(v)
            if field == 'type':
                p['type'] = index[key]
            else:
                c['props'][name] = index[key]
    out['types' if field == 'type' else 'props'] = table
    return out


def node_parse_ms(data):
    js = 'const fs=require("fs");const s=fs.readFileSync(0,"utf8");let t=[];for(let i=0;i<15;i++){const a=performance.now();JSON.parse(s);t.push(performance.now()-a)}t.sort((a,b)=>a-b);console.log(t[7].toFixed(1))'
    return subprocess.run(['node', '-e', js], input=data, capture_output=True, check=True).stdout.decode().strip()


print('| Corpus | Variant | Raw MB | gzip MB | Distinct / total | JSON.parse ms (Node) |')
print('| --- | --- | ---: | ---: | ---: | ---: |')
for corpus in sys.argv[1:] or ['mantine', 'spectrum']:
    raw = subprocess.run([BIN, 'extract', '--src', f'{IN}/{corpus}', '--json'], capture_output=True, check=True).stdout
    total = sum(len(c['props']) for c in json.loads(raw)['components'].values())
    for label, field in [('as today', None), ('types interned', 'type'), ('whole props interned', 'prop')]:
        out = json.loads(raw)
        if field:
            out = intern(out, field)
        data = json.dumps(out, separators=(',', ':')).encode()
        distinct = len(out['types'] if field == 'type' else out['props']) if field else total
        print(f'| {corpus} | {label} | {len(data) / 1e6:.1f} | {len(gzip.compress(data, 6)) / 1e6:.2f} | '
              f'{distinct:,} / {total:,} | {node_parse_ms(data)} |')

