82	    files: Arc<FxHashSet<Utf8PathBuf>>,
83	    /// `.d.ts` files the cold run parsed or loaded from the parse cache, and how many the cache answered.
84	    dts_files_parsed: u32,
85	    dts_cache_hits: u32,
86	    duration_ms: u64,
87	    pub(crate) output: Arc<ExtractionOutput>,
88	    /// The output key each component was published under.
89	    keys: FxHashMap<ComponentId, String>,
90	}
91	
92	/// The mapping identities of `global`, in output order: by file, then by position in the file.
93	fn component_ids<'g>(
94	    global: &'g GlobalSourceData,
95	    options: &PipelineOptions,
96	) -> Vec<(ComponentId, &'g ComponentMapping)> {
97	    let mut ordinals: FxHashMap<(&Utf8Path, &str), u32> = FxHashMap::default();
98	    let mut ids: Vec<(ComponentId, &ComponentMapping)> = global
99	        .component_mappings
100	        .iter()
101	        .filter(|m| !should_skip(&m.component_name, &options.exclude_prefixes))
102	        .map(|m| {
103	            let ordinal = ordinals.entry((m.file_path.as_path(), m.component_name.as_str())).or_insert(0);
104	            let id = ComponentId { file: m.file_path.clone(), name: m.component_name.clone(), ordinal: *ordinal };
105	            *ordinal += 1;
106	            (id, m)
107	        })
108	        .collect();
109	    ids.sort_by(|(a, ma), (b, mb)| (&a.file, ma.span_start, a.ordinal).cmp(&(&b.file, mb.span_start, b.ordinal)));
110	    ids
111	}
112	
113	fn resolve_all(
114	    mappings: &[(ComponentId, &ComponentMapping)],
115	    ctx: &ResolutionContext,
116	) -> FxHashMap<ComponentId, Arc<Resolved>> {
117	    let borrowed: Vec<&ComponentMapping> = mappings.iter().map(|(_, m)| *m).collect();
118	    resolve_guarded(&borrowed, ctx)
119	        .into_iter()
120	        .zip(mappings)
121	        .map(|((entry, diagnostics, depends_on), (id, _))| {
122	            (id.clone(), Arc::new(Resolved { entry, diagnostics, depends_on }))
123	        })
124	        .collect()
125	}
126	
127	impl Revision {
128	    /// Discover, parse, merge, resolve and assemble every source file.
129	    pub(crate) fn cold(options: &PipelineOptions, id: u64) -> Revision {
130	        let start = Instant::now();
131	        let mut head_diagnostics = source_dir_diagnostics(options);
132	
133	        let cache = Arc::new(DtsCache::load_from_disk(options.cache_dir.as_deref()));
134	        head_diagnostics.extend(cache.load_diagnostic().cloned());
135	
136	        let (src_files, discover_diagnostics) = discover_files(&options.src_dirs, &options.exclude_patterns);
137	        head_diagnostics.extend(discover_diagnostics);
138	
139	        // The whole closure body is wrapped in `contain_panic` so one file's parse panicking degrades to a per-file
140	        // diagnostic instead of poisoning the `.collect()` and crashing the whole extraction run.
141	        let parsed: Vec<(Utf8PathBuf, SourceData, Option<Diagnostic>)> = src_files
142	            .par_iter()
143	            .map(|path| {
144	                let label = format!("parse:{path}");
145	                crate::panic_guard::contain_panic(&label, || {
146	                    #[cfg(test)]
147	                    if path.file_name() == Some(super::PARSE_PANIC_TEST_SENTINEL) {
148	                        panic!("simulated parse-phase panic (test-only sentinel)");
149	                    }
150	                    let (data, io_diag) = parse_source_file(path, &cache);
151	                    (path.clone(), data, io_diag)
152	                })
153	                .unwrap_or_else(|diag| (path.clone(), SourceData::default(), Some(diag)))
154	            })
155	            .collect();
156	
157	        let mut global = GlobalSourceData::default();
158	        let mut file_diagnostics: BTreeMap<Utf8PathBuf, Vec<Diagnostic>> = BTreeMap::new();
159	        for (path, mut data, io_diag) in parsed {
160	            let mut diags: Vec<Diagnostic> = io_diag.into_iter().collect();
161	            diags.append(&mut data.diagnostics);
162	            diags.extend(options.plugins.run_on_file_extracted(&path, &mut data));
163	            if !diags.is_empty() {
164	                file_diagnostics.insert(path.clone(), diags);
165	            }
166	            global.merge(&path, data);
167	        }
168	
169	        let mut lib_diagnostics = Vec::new();
170	        // Full HTML attribute mode needs @types/react's real interfaces merged before resolution, so the resolver can
171	        // look them up like any other interface instead of only recording an InheritedLayer.
172	        if options.html_attributes == HtmlAttributeMode::Full {
173	            let from_dir = canonicalize_first_src_dir(&options.src_dirs).unwrap_or_else(|| Utf8PathBuf::from("."));
174	            match crate::resolver::resolve_package_dts_path(&from_dir, "react") {
175	                Some(react_dts_path) => {
176	                    let react_dts_path = Utf8PathBuf::from(react_dts_path);
177	                    merge_cached_dts_file(&react_dts_path, &cache, &mut global, &mut lib_diagnostics);
178	                }
179	                None => lib_diagnostics.push(
180	                    Diagnostic::new(
181	                        DiagnosticSeverity::Warning,
182	                        DiagnosticCode::MissingTypeLibrary,
183	                        "HtmlAttributeMode::Full requested but @types/react could not be resolved",
184	                    )
185	                    .with_help("Check that @types/react is installed. Falling back to curated attributes."),
186	                ),
187	            }
188	        }
189	        // Ambient globals (Date, Element, ...) live in TS's lib files and are never imported, so merge them in every
190	        // mode. An install missing a lib file (TS 7 without its platform package) is reported here.
191	        if let Some(from_dir) = canonicalize_first_src_dir(&options.src_dirs) {
192	            let libs = crate::resolver::resolve_ts_lib_paths(&from_dir);
193	            lib_diagnostics.extend(libs.diagnostic);
194	            for lib_path in libs.paths {
195	                merge_cached_dts_file(&Utf8PathBuf::from(lib_path), &cache, &mut global, &mut lib_diagnostics);
196	            }
197	        }
198	
199	        let global = Arc::new(global);
200	        let named_types = Arc::new(NamedTypeIndex::build(&global));
201	        let ambient_global_files = crate::resolver::compute_ambient_global_files(options);
202	        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
203	            global.clone(),
204	            options,
205	            ambient_global_files.clone(),
206	            named_types.clone(),
207	        );
208	        let resolved = resolve_all(&component_ids(&global, options), &ctx);
209	        let files = Arc::new(src_files.into_iter().collect());
210	
211	        let (dts_files_parsed, dts_cache_hits) = cache.counts();
212	        // Arc::try_unwrap succeeds because all rayon workers have finished.
213	        let tail_diagnostics: Vec<Diagnostic> = match Arc::try_unwrap(cache) {
214	            Ok(c) => c.save_to_disk(),
215	            Err(arc) => arc.save_to_disk(),
216	        }
217	        .into_iter()
218	        .collect();
219	
220	        let mut revision = Revision {
221	            id,
222	            global,
223	            named_types,
224	            ambient_global_files,
225	            head_diagnostics,
226	            file_diagnostics,
227	            lib_diagnostics,
228	            tail_diagnostics,
229	            resolved,
230	            files,
231	            dts_files_parsed,
232	            dts_cache_hits,
233	            duration_ms: 0,
234	            output: Arc::new(empty_output()),
235	            keys: FxHashMap::default(),
236	        };
237	        revision.duration_ms = start.elapsed().as_millis() as u64;
238	        revision.assemble(options);
239	        revision
240	    }
241	
242	    /// The revision after `changed` was edited, created or deleted, and the delta from this one. `None` when the path
243	    /// is not a source file of this project (outside every source directory, excluded, or not TypeScript).
244	    pub(crate) fn next(&self, options: &PipelineOptions, changed: &Utf8Path) -> Option<(Revision, IncrementalUpdate)> {
245	        if !is_source_file(changed, &options.src_dirs, &options.exclude_patterns) {
246	            return None;
247	        }
248	        let start = Instant::now();
249	
250	        let mut global = (*self.global).clone();
251	        let mut named_types = (*self.named_types).clone();
252	        let mut file_diagnostics = self.file_diagnostics.clone();
253	        let mut files = (*self.files).clone();
254	        let mut bare_names: FxHashSet<String> = bare_names_declared(changed, &self.global.enums).into_iter().collect();
255	        bare_names.extend(bare_names_declared(changed, &self.global.const_arrays));
256	        global.remove_file(changed);
257	        named_types.remove_file(changed);
258	        file_diagnostics.remove(changed);
259	
260	        let read = match std::fs::read_to_string(changed) {
261	            Ok(source) => Some((source, None)),
262	            // Deleted: its declarations and diagnostics leave with it.
263	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
264	            // Unreadable (permissions, invalid UTF-8): declares nothing, exactly as in a cold run.
265	            Err(e) => Some((String::new(), Some(Diagnostic::io_read_error(changed, &e)))),
266	        };
267	        let created = match read {
268	            None => {
269	                files.remove(changed);
270	                false
271	            }
272	            Some((source, io_diag)) => {
273	                let mut data = crate::extractor::parse_file(changed, &source);
274	                let mut diags: Vec<Diagnostic> = io_diag.into_iter().collect();
275	                diags.append(&mut data.diagnostics);
276	                diags.extend(options.plugins.run_on_file_extracted(changed, &mut data));
277	                if !diags.is_empty() {
278	                    file_diagnostics.insert(changed.to_owned(), diags);
279	                }
280	                bare_names.extend(bare_names_declared(changed, &data.enums));
281	                bare_names.extend(bare_names_declared(changed, &data.const_arrays));
282	                named_types.merge_file(&data);
283	                global.merge(changed, data);
284	                files.insert(changed.to_owned())
285	            }
286	        };
287	        let change = Change { file: changed, created, bare_names };
288	
289	        let global = Arc::new(global);
290	        let named_types = Arc::new(named_types);
291	        let ids = component_ids(&global, options);
292	        let (stale, kept): (Vec<_>, Vec<_>) = ids.into_iter().partition(|(id, _)| match self.resolved.get(id) {
293	            None => true,
294	            Some(previous) => id.file == changed || previous.affected_by(&change),
295	        });
296	        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
297	            global.clone(),
298	            options,
299	            self.ambient_global_files.clone(),
300	            named_types.clone(),
301	        );
302	        let fresh = resolve_all(&stale, &ctx);
303	        let mut resolved: FxHashMap<ComponentId, Arc<Resolved>> =
304	            kept.into_iter().filter_map(|(id, _)| self.resolved.get(&id).map(|r| (id, r.clone()))).collect();
305	        let fresh_ids: Vec<ComponentId> = fresh.keys().cloned().collect();
306	        resolved.extend(fresh);
307	
308	        let mut next = Revision {
309	            id: self.id + 1,
310	            global,
311	            named_types,
312	            ambient_global_files: self.ambient_global_files.clone(),
313	            head_diagnostics: self.head_diagnostics.clone(),
314	            file_diagnostics,
315	            lib_diagnostics: self.lib_diagnostics.clone(),
316	            tail_diagnostics: self.tail_diagnostics.clone(),
317	            resolved,
318	            files: Arc::new(files),
319	            dts_files_parsed: self.dts_files_parsed,
320	            dts_cache_hits: self.dts_cache_hits,
321	            duration_ms: self.duration_ms,
322	            output: Arc::new(empty_output()),
323	            keys: FxHashMap::default(),
324	        };
325	        next.assemble(options);
326	
327	        // Updated: every key whose component this revision re-resolved, plus every kept component whose key moved (a
328	        // same-named component elsewhere appeared or disappeared, so the bare and disambiguated keys swapped).
329	        let fresh: FxHashSet<&ComponentId> = fresh_ids.iter().collect();
330	        let mut updated_keys: Vec<&String> = next
331	            .keys
332	            .iter()
333	            .filter(|(id, key)| fresh.contains(id) || self.keys.get(*id) != Some(*key))
334	            .map(|(_, key)| key)
335	            .collect();
336	        updated_keys.sort();
337	        updated_keys.dedup();
338	        let updated_components: Vec<(String, ComponentEntry)> = updated_keys
339	            .into_iter()
340	            .filter_map(|key| Some((key.clone(), next.output.components.get(key)?.clone())))
341	            .collect();
342	        let removed_keys: Vec<String> =
343	            self.output.components.keys().filter(|key| !next.output.components.contains_key(*key)).cloned().collect();
344	        let mut affected_files: Vec<Utf8PathBuf> = fresh_ids.iter().map(|id| id.file.clone()).collect();
345	        affected_files.sort();
346	        affected_files.dedup();
347	        let before: FxHashSet<&Diagnostic> = self.output.diagnostics.iter().collect();
348	        let after: FxHashSet<&Diagnostic> = next.output.diagnostics.iter().collect();
349	        let diagnostics: Vec<Diagnostic> =
350	            next.output.diagnostics.iter().filter(|d| !before.contains(d)).cloned().collect();
351	        let removed_diagnostics: Vec<Diagnostic> =
352	            self.output.diagnostics.iter().filter(|d| !after.contains(d)).cloned().collect();
353	        let update = IncrementalUpdate {
354	            revision: next.id,
355	            updated_components: updated_components.iter().map(|(_, entry)| entry.clone()).collect(),
356	            updated_keys: updated_components.into_iter().map(|(key, _)| key).collect(),
357	            removed_keys,
358	            affected_files,
359	            diagnostics,
360	            removed_diagnostics,
361	            duration_ms: start.elapsed().as_millis() as u64,
362	        };
363	        Some((next, update))
364	    }
365	
366	    /// Build the public output from the revision: components keyed with the same disambiguation rule everywhere,
367	    /// plugin hooks applied, diagnostics in a stable order, public enums.
368	    fn assemble(&mut self, options: &PipelineOptions) {
369	        let mut diagnostics = DiagnosticSet::default();
370	        diagnostics.extend(self.head_diagnostics.iter().cloned(), None);
371	        for diags in self.file_diagnostics.values() {
372	            diagnostics.extend(diags.iter().cloned(), None);
373	        }
374	        diagnostics.extend(self.lib_diagnostics.iter().cloned(), None);
375	
376	        let mut components = BTreeMap::new();
377	        let mut keys = FxHashMap::default();
378	        let mut seen_names: FxHashMap<String, u32> = FxHashMap::default();
379	        for (id, _) in component_ids(&self.global, options) {
380	            let Some(resolved) = self.resolved.get(&id) else { continue };
381	            let mut entry = resolved.entry.clone();
382	            let base_name = entry.display_name.clone();
383	            let count = seen_names.entry(base_name.clone()).or_insert(0);
384	            *count += 1;
385	            // The first occurrence of a name keeps it bare; later ones take their file path, which is unique per file.
386	            let key = if *count == 1 { base_name } else { format!("{} ({})", base_name, entry.file_path) };
387	            diagnostics.extend(options.plugins.run_on_component_resolved(&mut entry), Some(&key));
388	            let new_file_path = entry.file_path.clone();
389	            if let Some(previous) = components.insert(key.clone(), entry) {
390	                diagnostics.add(
391	                    Diagnostic::new(
392	                        DiagnosticSeverity::Warning,
393	                        DiagnosticCode::ComponentKeyCollision,
394	                        format!(
395	                            "Duplicate component key '{key}' — colliding file paths: previously '{}', now '{}'",
396	                            previous.file_path, new_file_path
397	                        ),
398	                    )
399	                    .with_file(new_file_path.to_string())
400	                    .with_help(
401	                        "Two resolved components produced the same display name and disambiguation key — only the \
402	                         later one is kept in the output. Check for overlapping src_dirs or a genuine duplicate \
403	                         declaration.",
404	                    ),
405	                    None,
406	                );
407	            }
408	            diagnostics.extend(resolved.diagnostics.iter().cloned(), Some(&key));
409	            keys.insert(id, key);
410	        }
411	
412	        let (enums, enum_diagnostics) = collect_public_enums(&self.global);
413	        diagnostics.extend(enum_diagnostics, None);
414	        diagnostics.extend(self.tail_diagnostics.iter().cloned(), None);
415	
416	        let components_extracted = components.len() as u32;
417	        self.output = Arc::new(ExtractionOutput {
418	            components,
419	            enums,
420	            diagnostics: diagnostics.finish(),
421	            stats: ExtractionStats {
422	                components_extracted,
423	                files_parsed: self.files.len() as u32,
424	                dts_files_parsed: self.dts_files_parsed,
425	                dts_cache_hits: self.dts_cache_hits,
426	                duration_ms: self.duration_ms,
427	                ..Default::default()
428	            },
429	        });
430	        self.keys = keys;
431	    }
432	}
433	
434	/// Diagnostics merged by identity: an identical diagnostic reported while resolving many components is kept once,
435	/// listing those components in `affects`.
436	#[derive(Default)]
437	struct DiagnosticSet {
438	    index: FxHashMap<Diagnostic, usize>,
439	    items: Vec<Diagnostic>,
440	}
441	
442	impl DiagnosticSet {
443	    fn add(&mut self, diagnostic: Diagnostic, component: Option<&str>) {
444	        let at = match self.index.get(&diagnostic) {
445	            Some(&at) => at,
446	            None => {
447	                self.index.insert(diagnostic.clone(), self.items.len());
448	                self.items.push(diagnostic);
449	                self.items.len() - 1
450	            }
451	        };
452	        if let Some(key) = component {
453	            self.items[at].affects.push(key.to_owned());
454	        }
455	    }
456	
457	    fn extend(&mut self, diagnostics: impl IntoIterator<Item = Diagnostic>, component: Option<&str>) {
458	        for diagnostic in diagnostics {
459	            self.add(diagnostic, component);
460	        }
461	    }
462	
463	    /// The diagnostics by file, position and message; run-wide ones (no file) first.
464	    fn finish(self) -> Vec<Diagnostic> {
465	        let mut items = self.items;
466	        for diagnostic in &mut items {
467	            diagnostic.affects.sort();
468	            diagnostic.affects.dedup();
469	        }
470	        // Severity by explicit rank, worst first, and code by name: neither enum's declaration order is an ordering.
471	        items.sort_by(|a, b| {
472	            (&a.file, a.line, a.column, &a.message)
473	                .cmp(&(&b.file, b.line, b.column, &b.message))
474	                .then_with(|| severity_rank(&b.severity).cmp(&severity_rank(&a.severity)))
475	                .then_with(|| format!("{:?}", a.code).cmp(&format!("{:?}", b.code)))
476	                .then_with(|| a.help.cmp(&b.help))
477	        });
478	        items
479	    }
480	}
481	
482	/// Read and parse one source file, through the parse cache for `.d.ts`.
483	fn parse_source_file(path: &Utf8Path, cache: &DtsCache) -> (SourceData, Option<Diagnostic>) {
484	    let is_dts = path.as_str().ends_with(".d.ts");
485	    let (source, io_diag) = match std::fs::read_to_string(path) {
486	        Ok(s) => (s, None),
487	        Err(e) => (String::new(), Some(Diagnostic::io_read_error(path, &e))),
488	    };
489	    if is_dts {
490	        if let Some(cached) = cache.get(path, &source) {
491	            return (cached, io_diag);
492	        }
493	    }
494	    let data = crate::extractor::parse_file(path, &source);
495	    if is_dts {
496	        cache.insert(path, &source, data.clone());
497	    }
498	    (data, io_diag)
499	}
500	
501	/// A typo'd `--src` (or a stale config `srcDirs`) must not silently produce an empty-but-valid-looking result.
502	fn source_dir_diagnostics(options: &PipelineOptions) -> Vec<Diagnostic> {
503	    let missing: Vec<&Utf8PathBuf> = options.src_dirs.iter().filter(|dir| !dir.as_std_path().is_dir()).collect();
504	    let help = "Check --src (or docgen.config.ts srcDirs) for a typo'd or stale path.";
505	    if options.src_dirs.is_empty() {
506	        return vec![Diagnostic::new(
507	            DiagnosticSeverity::Error,
508	            DiagnosticCode::IoError,
509	            "No source directories configured — src_dirs is empty",
510	        )
511	        .with_help("Set --src (or docgen.config.ts srcDirs) to at least one directory to scan.")];
512	    }
513	    if missing.len() == options.src_dirs.len() {
514	        let mut diag = Diagnostic::new(
515	            DiagnosticSeverity::Error,
516	            DiagnosticCode::IoError,
517	            format!(
518	                "None of the configured source directories exist: {}",
519	                options.src_dirs.iter().map(|dir| dir.as_str()).collect::<Vec<_>>().join(", ")
520	            ),
521	        )
522	        .with_help(help);
523	        if let Some(first) = options.src_dirs.first() {
524	            diag = diag.with_file(first.to_string());
525	        }
526	        return vec![diag];
527	    }
528	    missing
529	        .into_iter()
530	        .map(|dir| {
531	            Diagnostic::new(
532	                DiagnosticSeverity::Warning,
533	                DiagnosticCode::IoError,
534	                format!("Source directory does not exist: {dir}"),
535	            )
536	            .with_file(dir.to_string())
537	            .with_help(help)
538	        })
539	        .collect()
540	}
541	
542	fn empty_output() -> ExtractionOutput {
543	    ExtractionOutput {
544	        components: BTreeMap::new(),
545	        enums: BTreeMap::new(),
546	        diagnostics: Vec::new(),
547	        stats: ExtractionStats::default(),
548	    }
549	}
