2	
3	use camino::Utf8PathBuf;
4	use serde::{Deserialize, Serialize};
5	use std::collections::BTreeMap;
6	
7	use super::collected::{EnumEntry, TypeName};
8	use super::diagnostic::{Diagnostic, DiagnosticSeverity};
9	use super::global::ResolveState;
10	
11	// ─── Top-level output ─────────────────────────────────────────────────────────
12	
13	/// The complete extraction output — top-level return type of the pipeline.
14	#[must_use]
15	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
16	#[serde(rename_all = "camelCase")]
17	pub struct ExtractionOutput {
18	    /// Extracted component entries, keyed by component name
19	    pub components: BTreeMap<String, ComponentEntry>,
20	    /// Enum definitions discovered during extraction
21	    pub enums: BTreeMap<String, Vec<EnumEntry>>,
22	    /// Non-fatal issues encountered during extraction
23	    pub diagnostics: Vec<Diagnostic>,
24	    /// Extraction statistics
25	    pub stats: ExtractionStats,
26	}
27	
28	impl ExtractionOutput {
29	    /// Highest-severity diagnostic present, if any — `Error` outranks
30	    /// `Warning` outranks `Info`. Ranked explicitly rather than via derived
31	    /// `Ord` on `DiagnosticSeverity`, since that enum has no ordering today
32	    /// and its declaration order isn't a promise about severity ranking.
33	    pub fn max_severity(&self) -> Option<DiagnosticSeverity> {
34	        self.diagnostics.iter().map(|d| d.severity.clone()).max_by_key(severity_rank)
35	    }
36	
37	    /// Process exit code for this output: `2` if any diagnostic is
38	    /// `Error`-severity, `1` if `strict` and any diagnostic is at least
39	    /// `Warning`-severity, `0` otherwise. This is the CLI's shared exit-code
40	    /// contract — `caliper-docgen check --strict`'s mapping, reused as-is
41	    /// by `extract`, `watch`, and `inspect`.
42	    pub fn exit_code(&self, strict: bool) -> i32 {
43	        match self.max_severity() {
44	            Some(DiagnosticSeverity::Error) => 2,
45	            Some(DiagnosticSeverity::Warning) => {
46	                if strict {
47	                    1
48	                } else {
49	                    0
50	                }
51	            }
52	            Some(DiagnosticSeverity::Info) => 0,
53	            None => 0,
54	        }
55	    }
56	}
57	
58	/// Explicit worst-first rank for `DiagnosticSeverity` — `Error` > `Warning` > `Info`.
59	pub(crate) fn severity_rank(severity: &DiagnosticSeverity) -> u8 {
60	    match severity {
61	        DiagnosticSeverity::Error => 2,
62	        DiagnosticSeverity::Warning => 1,
63	        DiagnosticSeverity::Info => 0,
64	    }
65	}
