    fn add<E: serde::ser::Error>(&mut self, rows: Vec<Row<'a>>) -> Result<Vec<(&'a str, PropId)>, E> {
        rows.into_iter()
            .map(|(name, id, prop, json)| {
                match self.entries.get(&id) {
