import { describe, it, expect, vi, beforeEach } from 'vitest'

const SNAPSHOT = JSON.stringify({
  components: { Button: { displayName: 'Button' } },
  enums: {},
  diagnostics: [],
  stats: {},
})

const component = (displayName: string, description = '') => ({
  displayName,
  filePath: `/project/src/${displayName}.tsx`,
  props: {},
  inheritance: [],
  notableInherited: {},
  description,
  discriminantProp: null,
  composes: [],
  tags: {},
  methods: [],
})

const update = (revision: number, updated: string[], removed: string[] = [], description = '') =>
  JSON.stringify({
    revision,
    updatedComponents: updated.map((name) => component(name, description)),
    updatedKeys: updated,
    removedKeys: removed,
    affectedFiles: [],
    diagnostics: [],
    removedDiagnostics: [],
    durationMs: 1,
  })

// Mock BEFORE importing plugin — vi.mock is hoisted by Vitest
vi.mock('caliper-docgen-napi', () => ({
  createSession: vi.fn().mockReturnValue(42),
  initializeSession: vi.fn(),
  extractFileIncremental: vi.fn(),
  closeSession: vi.fn(),
      )
    })

    it('sends the keyed update over HMR', async () => {
      ;(napi.extractFileIncremental as any).mockResolvedValueOnce(update(2, ['Panel'], ['Card']))
      const ctx = clientEnv()
      await (plugin.hotUpdate as Function).call(ctx, makeOpts('/project/src/Card.tsx'))
      expect(sentUpdates(ctx)).toEqual([
        {
          file: '/project/src/Card.tsx',
          revision: 2,
          updatedKeys: ['Panel'],
          updatedComponents: [component('Panel')],
          removedKeys: ['Card'],
          diagnostics: [],
          removedDiagnostics: [],
        },
      ])
    })

    it('invalidates the virtual module and returns it with the changed modules', async () => {
      const ctx = clientEnv(true)
      const result = await (plugin.hotUpdate as Function).call(ctx, makeOpts('/project/src/Button.tsx'))
      expect(ctx.environment.moduleGraph.invalidateModule).toHaveBeenCalledWith(virtualModule)
      expect(result).toEqual([changedModule, virtualModule])
    })
  it('resolves the virtual module with real extracted data for a real fixture file', async () => {
    server = await createServer({
      configFile: false,
      root: FIXTURES_ROOT,
      server: { middlewareMode: true },
      plugins: [caliperDocgen({ srcDirs: ['src'] })],
    })

    const data = await waitForComponents(server)

    expect(data.components).toHaveProperty('Button')
    const button = data.components.Button
    expect(Object.keys(button.props).toSorted()).toEqual(['label', 'onClick', 'variant'])
    expect(button.props.label.required).toBe(true)
    expect(button.props.variant.required).toBe(false)
    // The NAPI boundary's ParsedProp.defaultValue.value carries the prop's
    // source-text literal verbatim, quotes included — not a bare JS string.
    expect(button.props.variant.defaultValue?.value).toBe('"primary"')
  })

  it('re-extracts real prop changes via a direct hotUpdate call against the real binding', async () => {
    const plugin = caliperDocgen({ srcDirs: ['src'] })
    server = await createServer({
      configFile: false,
      root: FIXTURES_ROOT,
      server: { middlewareMode: true },
      plugins: [plugin],
    })

    await waitForComponents(server)

    // Real edit to the real fixture file — a genuinely new prop.
    fs.writeFileSync(
      BUTTON_FIXTURE,
      `export interface ButtonProps {
  label: string
  disabled?: boolean
}
export function Button({ label, disabled = false }: ButtonProps) {
  return <button disabled={disabled}>{label}</button>
}
`,
    )

    const hotSend: Array<{ event: string; data: unknown }> = []
    const ctx = {
      environment: {
        name: 'client',
        hot: { send: (event: string, data: unknown) => hotSend.push({ event, data }) },
      },
    }
    await (plugin.hotUpdate as any).call(ctx, {
      file: BUTTON_FIXTURE,
      type: 'update',
      modules: [],
      timestamp: Date.now(),
      read: async () => fs.readFileSync(BUTTON_FIXTURE, 'utf8'),
      server,
    })

    const updateEvent = hotSend.find((e) => e.event === 'caliper-docgen:update')
    expect(updateEvent).toBeDefined()
    const updated = (updateEvent!.data as any).updatedComponents[0]
    expect(updated.displayName).toBe('Button')
    expect(Object.keys(updated.props).toSorted()).toEqual(['disabled', 'label'])

    const data = await loadVirtualModule(server)
    expect(Object.keys(data.components.Button.props).toSorted()).toEqual(['disabled', 'label'])
  })

  it('serves dependency edits and deletions through the virtual module and the update event', async () => {
# caliper-docgen-vite-plugin

A Vite plugin that exposes your React components' props on a virtual module and updates it through HMR as you edit.

```bash
npm install --save-dev caliper-docgen-vite-plugin
```

```ts
// vite.config.ts
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import { caliperDocgen } from 'caliper-docgen-vite-plugin'

export default defineConfig({
  plugins: [react(), caliperDocgen({ srcDirs: ['src'] })],
})
```

```ts
import docgen from 'virtual:caliper-docgen'

docgen.components['Button'].props
```

On every change the virtual module reloads with the same output a fresh extraction would give, including removed components, enums and diagnostics. To apply changes yourself, listen for the update event:

```ts
import.meta.hot?.on(
  'caliper-docgen:update',
  ({ updatedKeys, updatedComponents, removedKeys, diagnostics, removedDiagnostics }) => {
    // Events arrive in revision order, each a delta from the one before: delete removedKeys, set updatedKeys[i] to
    // updatedComponents[i], drop removedDiagnostics and add diagnostics.
  },
)
```

In `vite build --watch`, a change to any file under `srcDirs` triggers a rebuild, even one no bundle module imports. A build fails if extraction fails.

Extraction runs on OXC through [`caliper-docgen-napi`](https://www.npmjs.com/package/caliper-docgen-napi), so a single-file update takes about 2ms. Requires Vite 7 or 8. The module uses the canonical output format, not the `react-docgen-typescript` shape.

Docs and benchmarks: [orin-dx.com/tools/caliper](https://orin-dx.com/tools/caliper/). Source: [github.com/orin-dx/caliper](https://github.com/orin-dx/caliper).

## License

FSL-1.1-MIT. Each version becomes MIT two years after its release.

