        let extends: Vec<&str> = match config.get("extends") {
            Some(serde_json::Value::String(base)) => vec![base.as_str()],
            Some(serde_json::Value::Array(bases)) => bases.iter().rev().filter_map(|b| b.as_str()).collect(),
            _ => Vec::new(),
