/// naming convention (e.g. `@babel/core` -> `@types/babel__core`). Unscoped names
/// pass through unchanged.
fn mangle_scoped_package_name(name: &str) -> String {
    name.strip_prefix('@').map_or_else(|| name.to_owned(), |rest| rest.replacen('/', "__", 1))
}

